export function runConfig(positionals, { cwd, env, repo, dryRun }) {
  const [sub, key, value] = positionals;
  const need = (n) => { if (positionals.length !== n) throw usageError(`config ${sub} cần ${n - 1} đối số`, { fix: 'momentry config --help' }); };
  switch (sub) {
