    $local = $env:LOCALAPPDATA
    if (-not $local) { $local = Join-Path $HOME 'AppData\Local' }
    $homeDir = if ($env:MOMENTRY_HOME) { $env:MOMENTRY_HOME } else { Join-Path $local 'momentry' }
    $binDir = if ($env:MOMENTRY_INSTALL_DIR) { $env:MOMENTRY_INSTALL_DIR } else { Join-Path $homeDir 'bin' }
