            if ($LASTEXITCODE -ne 0) { throw "failed to extract $asset" }
            $entry = Join-Path $stage "$top\bin\momentry.mjs"
            $reported = (& node $entry --version 2>$null | Select-Object -First 1)
            if ($reported -ne "momentry $($version.Substring(1))") {
                Remove-Item -LiteralPath $stage -Recurse -Force
                throw "the downloaded version does not run here ($reported)"
            }
            if ($current -ne $version -and (Test-Path -LiteralPath $dest)) { Remove-Item -LiteralPath $dest -Recurse -Force }
            if (-not (Test-Path -LiteralPath $dest)) { Move-Item -LiteralPath (Join-Path $stage $top) -Destination $dest }
            Remove-Item -LiteralPath $stage -Recurse -Force -ErrorAction SilentlyContinue
