      lastTool = null;
    } else if (o.type === 'PLANNER_RESPONSE') {
      if (typeof o.content === 'string' && o.content.trim()) out.push({ L, ts, kind: 'assistant', text: o.content });
      for (const c of Array.isArray(o.tool_calls) ? o.tool_calls : []) {
