      const code = EXIT_RE.exec(text);
      out.push({ L, ts, kind: 'result', name: lastTool.name, text, isError: o.status === 'ERROR', exitCode: code ? Number(code[1]) : null });
      lastTool = null;
    }
  }
  return out;
}

