  const detail = worst === 'ok' ? `${ts.length} profile đã cài` : parts.filter((r) => r.status === worst).map((r) => r.detail).slice(0, 3).join('; ') + (missing.length > 1 ? ` (+${missing.length} profile chưa cài)` : '');
