const CMD_RE = new RegExp(String.raw`(?:"cmd"|'cmd'|\bcmd)\s*:\s*(${LITERAL})`, 'g');
const LIT_RE = new RegExp(LITERAL, 'g');

/** `codex:<first 8 chars of uuid>` from a rollout path. @param {string} file @returns {string} */
export function sessionId(file) {
  const m = path.basename(file).match(UUID_RE);
  return 'codex:' + (m ? m[1] : path.basename(file, '.jsonl').slice(-8)).toLowerCase();
}

/** Reads the `session_meta` line. @param {string} file @returns {{id: string|null, cwd: string|null, ts: string|null}} */
const blank = () => ({ source: null, transcriptPath: null, repoRoot: null, lastLine: 0, size: 0, mtimeMs: 0, status: null, pending: false, needsRescore: [], mainGoals: [], harvests: [] });

/** Missing file -> empty ledger. @param {string} cacheDir @returns {Ledger} */
export function load(cacheDir) {
  let text;
  try { text = fs.readFileSync(path.join(cacheDir, FILE), 'utf8'); } catch (e) {
    if (e.code === 'ENOENT') return empty();
    throw e;
  }
  const v = JSON.parse(text);
  if (!v || typeof v !== 'object' || typeof v.sessions !== 'object' || !v.sessions) return empty();
  return { version: 1, sessions: v.sessions, repos: v.repos && typeof v.repos === 'object' ? v.repos : {} };
}

